,p_process_name=>'Insert order'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_count NUMBER;',
'BEGIN',
'    IF :P9_CREATE_REQUEST = 1 THEN',
'        IF LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => :P9_TYPE_SELLER) = ''owner'' THEN',
'            IF :P9_BUYER_TYPE = ''INDIVIDUAL'' THEN',
'                INSERT INTO INDIVIDUAL_REALESTATE_REQUESTS (BUYER_ID, BUYER_NAME, BUYER_TYPE, BUYER_NATIONAL_ID, BUYER_PHONE, REQUESTER_AS, STATUS)',
'                    VALUES (:P9_BUYER_ID, :P9_NAME, :P9_BUYER_TYPE, :P9_NID, :P9_PHONE, :P9_TYPE_SELLER,',
'                            LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''submit_request'', p_lookup_code => ''individual_request_status''))',
'                RETURNING ID INTO :P9_ORDER_ID;',
'            ELSIF :P9_BUYER_TYPE = ''COMMERCIAL'' THEN',
'                INSERT INTO INDIVIDUAL_REALESTATE_REQUESTS (BUYER_ID, BUYER_NAME, BUYER_TYPE, BUYER_NATIONAL_ID, BUYER_PHONE, COMPANY_NAME, COMMERCIAL_REGISTER, AUTHORIZATION_NAME, AUTHORIZATION_NID, AUTHORIZATION_PHONE,',
'                                                            REQUESTER_AS, STATUS)',
'                    VALUES (:P9_BUYER_ID, :P9_NAME, :P9_BUYER_TYPE, :P9_NID, :P9_PHONE, :P9_COMPANY_NAME, :P9_COMMERCIAL_REGISTER, :P9_COMMISSIONER_NAME, :P9_COMMISSIONER_ID_NUMBER, :P9_COMMISSIONER_MOBILE_NUMBER, :P9_TYPE_SELLER,',
'                            LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''submit_request'', p_lookup_code => ''individual_request_status''))',
'                RETURNING ID INTO :P9_ORDER_ID;',
'            END IF;',
'        ELSIF LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => :P9_TYPE_SELLER) = ''authorized'' THEN',
'            INSERT INTO INDIVIDUAL_REALESTATE_REQUESTS (BUYER_ID, BUYER_NAME, BUYER_TYPE, BUYER_NATIONAL_ID, BUYER_PHONE, AUTHORIZATION_NUMBER, AUTHORIZATION_DATE, AUTHORIZATION_ADDRESS, AUTHORIZATION_URL, REQUESTER_AS,',
'                                                        STATUS)',
'                VALUES (:P9_BUYER_ID, :P9_NAME, :P9_BUYER_TYPE, :P9_NID, :P9_PHONE, :P9_AGENCY_NUM, :P9_AGENCY_DATE, :P9_AGENCY_PLACE, :P9_AGENCY_LICENSE_URL, :P9_TYPE_SELLER,',
'                        LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''submit_request'', p_lookup_code => ''individual_request_status''))',
'            RETURNING ID INTO :P9_ORDER_ID;',
'        ELSIF LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => :P9_TYPE_SELLER) = ''real_estate_marketer'' THEN',
'            INSERT INTO INDIVIDUAL_REALESTATE_REQUESTS (BUYER_ID, BUYER_NAME, BUYER_TYPE, BUYER_NATIONAL_ID, BUYER_PHONE, VAL_LICENSE_NUMBER, LICENSE_TYPE, LICENSE_EXPIRY_DATE, VAL_LICENSE_URL,',
'                                                       MEDIATION_CONTRACT_URL, REQUESTER_AS, STATUS)',
'                VALUES (:P9_BUYER_ID, :P9_NAME, :P9_BUYER_TYPE, :P9_NID, :P9_PHONE, :P9_VAL_LICENSE_NUM, :P9_VAL_LICENSE_TYPE, :P9_EXPIRY_DATE, :P9_VAL_LICENSE_URL, :P9_VAL_LICENSE2_URL, :P9_TYPE_SELLER,',
'                        LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''submit_request'', p_lookup_code => ''individual_request_status''))',
'            RETURNING ID INTO :P9_ORDER_ID;',
'        ELSE',
'            RAISE_APPLICATION_ERROR(-20001, LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => :P9_TYPE_SELLER));',
'        END IF;',
'    -- ELSIF :P9_CREATE_REQUEST = 2 THEN',
'    --     IF :P9_NUM_REQ IS NOT NULL AND :P9_PHONE8 IS NOT NULL THEN',
'    --         SELECT count(1)',
'    --           INTO v_count',
