wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(136189591776352133)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload products images'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_name     VARCHAR2(255);',
'    l_request_url   VARCHAR2(32767);',
'    l_result	    CLOB;',
'    l_comma         VARCHAR2(3);',
'BEGIN',
'    IF APEX_COLLECTION.COLLECTION_EXISTS (p_collection_name => ''DROPZONE_UPLOAD'') THEN',
'        FOR i IN (SELECT c001 AS FILE_NAME, c002 AS MIME_TYPE, blob001 AS BLOB_CONTENT FROM apex_collections WHERE collection_name = ''DROPZONE_UPLOAD'') LOOP',
'            l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                                || DBMS_RANDOM.STRING(''x'', 8)',
'                                || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => i.MIME_TYPE);',
'',
'        l_request_url := :LOCATION_URI || l_file_name;',
'',
'        DBMS_CLOUD.put_object (',
'            credential_name => :CREDENTIAL_NAME,',
'            object_uri      => l_request_url,',
'            contents        => i.blob_content',
'        );',
'',
'            IF :P10_MORE_IMAGE = 1 THEN l_comma := '',''; END IF;',
'',
'            :P10_PRODUCT_IMAGES := :P10_PRODUCT_IMAGES || l_comma || l_request_url || '','';',
'        END LOOP;',
'',
'        :P10_PRODUCT_IMAGES := SUBSTR(:P10_PRODUCT_IMAGES, 1, LENGTH(:P10_PRODUCT_IMAGES) - 1);',
'',
'        -- TRUNCATE THE COLLECTION AFTER GET THE URLS',
'        APEX_COLLECTION.TRUNCATE_COLLECTION (p_collection_name => ''DROPZONE_UPLOAD'');',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>48659385408172007
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(134467067065819273)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Insert'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_buyer_id    NUMBER;',
'    v_product_id  NUMBER;',
'BEGIN',
'    SELECT BUYER_ID, PRODUCT_ID',
'      INTO v_buyer_id, v_product_id',
'      FROM INDIVIDUAL_REALESTATE_REQUESTS',
'     WHERE ID = :P10_ID_ORDER;',
'',
'    IF v_product_id IS NULL THEN',
'        INSERT INTO PRODUCTS (BUYER_ID, CITY_ID, CATEGORY_ID, SUB_CATEGORY_ID, MAIN_IMAGE_URL, IMAGES_URLS, MAP_URL, DESCRIPTION_AR, STATUS, IS_ACTIVE)',
'            VALUES (v_buyer_id, :P10_CITES, 1, :P10_BUILDING_TYPE, :P10_MAIN_IMAGE_URL, :P10_PRODUCT_IMAGES, :P10_MAP, :P10_DESCRIPTION,',
'                   LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''available'', p_lookup_code => ''product_status''), 0)',
'        RETURNING ID INTO v_product_id;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(-20001, ''Product Insertion Error'');',
'        END IF;',
'',
'        :P10_PRODUCT_ID := v_product_id;',
'',
'        INSERT INTO REAL_STATE_DETAILS (PRODUCT_ID, NEIGHBOURHOODS_ID, STREET_NAME_AR, USAGE_ID, FACADE_ID, PROPERTY_TYPE_ID, SPACE)',
'            VALUES (v_product_id, :P10_NEIGHBOURHOODS, :P10_STREET, :P10_BUILDING_USED, :P10_BUILDING_FACDE, :P10_BUILDING_TYPE, :P10_SPACE);',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(-20002, ''Real-Estate Insertion Error'');',
'        END IF;',
'',
'        UPDATE INDIVIDUAL_REALESTATE_REQUESTS',
'           SET PRODUCT_ID           = v_product_id,',
'               SHORT_ADDRESS        = :P10_SHORT_TITLE,',
'               BUILDING_NUMBER      = :P10_BUILDING_NUM,',
'               STREET_NAME          = :P10_STREET_NA,',
'               NEIGHBOURHOOD_NAME   = :P10_NEIGH,',
'               SUB_NUMBER           = :P10_SUBNUMBER,',
'               POSTAL_NUMBER        = :P10_ZIP_CODE,',
'               CONSTRUCTION_LICENSE_URL = :P10_CONSTRUCTION_LICENSE_URL,',
'               CADASTRAL_URL = :P10_CADASTRAL_URL',
'         WHERE ID = :P10_ID_ORDER;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(-20003, ''Indiviual Updating Error'');',
'        END IF;',
'',
'    IF APEX_COLLECTION.COLLECTION_EXISTS (p_collection_name => ''AUCTION_BULIDING_LENGTH'') THEN',
'        FOR i IN (SELECT c001 AS FACADE, c002 AS DESCRIPTION',
'                    FROM APEX_COLLECTIONS WHERE COLLECTION_NAME = ''AUCTION_BULIDING_LENGTH'')',
'        LOOP',
'            INSERT INTO PROPERTY_DIMENSIONS (PRODUCT_ID, FACADE_ID, DESCRIPTION_AR)',
'                VALUES (v_product_id, i.FACADE, i.DESCRIPTION);',
'',
'            IF SQL%ROWCOUNT = 0 THEN',
'                RAISE_APPLICATION_ERROR(-20004, ''PROPERTY_DIMENSIONS Insertion Error'');',
'            END IF;',
'        END LOOP;',
'        APEX_COLLECTION.TRUNCATE_COLLECTION (p_collection_name => ''AUCTION_BULIDING_LENGTH'');',
'    END IF;',
'',
'    IF APEX_COLLECTION.COLLECTION_EXISTS (p_collection_name => ''AUCTION_BULIDING_SERVICE'') THEN',
'        FOR j IN (SELECT c001 AS SERVICE, c002 AS DESCRIPTION',
'                    FROM APEX_COLLECTIONS WHERE COLLECTION_NAME = ''AUCTION_BULIDING_SERVICE'')',
'        LOOP',
'            INSERT INTO PROPERTY_SERVICES (PRODUCT_ID, SERVICE_ID, DESCRIPTION_AR)',
'                VALUES (v_product_id, j.SERVICE, j.DESCRIPTION);',
'',
'            IF SQL%ROWCOUNT = 0 THEN',
'                RAISE_APPLICATION_ERROR(-20005, ''PROPERTY_SERVICES Insertion Error'');',
'            END IF;',
'        END LOOP;',
'        APEX_COLLECTION.TRUNCATE_COLLECTION (p_collection_name => ''AUCTION_BULIDING_SERVICE'');',
'    END IF;',
'    ELSE',
'        UPDATE PRODUCTS',
'           SET CITY_ID          = :P10_CITES,',
'               SUB_CATEGORY_ID  = :P10_BUILDING_TYPE,',
'               MAIN_IMAGE_URL   = :P10_MAIN_IMAGE_URL,',
'               IMAGES_URLS      = :P10_PRODUCT_IMAGES',
'         WHERE ID = v_product_id;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(-20006, ''Product Updating Error'');',
'        END IF;',
'',
'        UPDATE REAL_STATE_DETAILS',
'           SET NEIGHBOURHOODS_ID    = :P10_NEIGHBOURHOODS,',
'               STREET_NAME_AR       = :P10_STREET,',
'               USAGE_ID             = :P10_BUILDING_USED,',
'               FACADE_ID            = :P10_BUILDING_FACDE,',
'               PROPERTY_TYPE_ID     = :P10_BUILDING_TYPE,',
'               SPACE                = :P10_SPACE',
'         WHERE PRODUCT_ID = v_product_id;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(-20007, ''Real-Estate Updating Error'');',
'        END IF;',
'',
'        UPDATE INDIVIDUAL_REALESTATE_REQUESTS',
'           SET SHORT_ADDRESS        = :P10_SHORT_TITLE,',
'               BUILDING_NUMBER      = :P10_BUILDING_NUM,',
'               STREET_NAME          = :P10_STREET_NA,',
'               NEIGHBOURHOOD_NAME   = :P10_NEIGH,',
'               SUB_NUMBER           = :P10_SUBNUMBER,',
'               POSTAL_NUMBER        = :P10_ZIP_CODE,',
'               CONSTRUCTION_LICENSE_URL = :P10_CONSTRUCTION_LICENSE_URL,',
'               CADASTRAL_URL = :P10_CADASTRAL_URL',
'         WHERE PRODUCT_ID = v_product_id;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(-20008, ''Indiviual Updating Error'');',
'        END IF;',
'',
'        IF APEX_COLLECTION.COLLECTION_EXISTS (p_collection_name => ''AUCTION_BULIDING_LENGTH'') THEN',
'            FOR i IN (SELECT c001 AS FACADE, c002 AS DESCRIPTION',
'                        FROM APEX_COLLECTIONS WHERE COLLECTION_NAME = ''AUCTION_BULIDING_LENGTH''',
'                         AND c001 NOT IN (SELECT FACADE_ID FROM PROPERTY_DIMENSIONS WHERE PRODUCT_ID = v_product_id))',
'            LOOP',
'                INSERT INTO PROPERTY_DIMENSIONS (PRODUCT_ID, FACADE_ID, DESCRIPTION_AR)',
'                    VALUES (v_product_id, i.FACADE, i.DESCRIPTION);',
'',
'                IF SQL%ROWCOUNT = 0 THEN',
'                    RAISE_APPLICATION_ERROR(-20009, ''PROPERTY_DIMENSIONS Insertion Error'');',
'                END IF;',
'            END LOOP;',
'            APEX_COLLECTION.TRUNCATE_COLLECTION (p_collection_name => ''AUCTION_BULIDING_LENGTH'');',
'        END IF;',
'',
'        IF APEX_COLLECTION.COLLECTION_EXISTS (p_collection_name => ''AUCTION_BULIDING_SERVICE'') THEN',
'            FOR j IN (SELECT c001 AS SERVICE, c002 AS DESCRIPTION',
'                        FROM APEX_COLLECTIONS WHERE COLLECTION_NAME = ''AUCTION_BULIDING_SERVICE''',
'                         AND c001 NOT IN (SELECT SERVICE_ID FROM PROPERTY_SERVICES WHERE PRODUCT_ID = v_product_id))',
'            LOOP',
'                INSERT INTO PROPERTY_SERVICES (PRODUCT_ID, SERVICE_ID, DESCRIPTION_AR)',
'                    VALUES (v_product_id, j.SERVICE, j.DESCRIPTION);',
'',
'                IF SQL%ROWCOUNT = 0 THEN',
'                    RAISE_APPLICATION_ERROR(-20010, ''PROPERTY_SERVICES Insertion Error'');',
'                END IF;',
'            END LOOP;',
'            APEX_COLLECTION.TRUNCATE_COLLECTION (p_collection_name => ''AUCTION_BULIDING_SERVICE'');',
'        END IF;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
