wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(136190915802352147)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Get data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_count NUMBER;',
'BEGIN',
'    IF :P10_PRODUCT_ID IS NOT NULL THEN',
'        SELECT CITY_ID, CATEGORY_ID, MAIN_IMAGE_URL, IMAGES_URLS',
'          INTO :P10_CITES, :P10_BUILDING_TYPE, :P10_MAIN_IMAGE_URL, :P10_PRODUCT_IMAGES',
'          FROM PRODUCTS',
'         WHERE ID = :P10_PRODUCT_ID;',
'',
'        SELECT NEIGHBOURHOODS_ID, STREET_NAME_AR, USAGE_ID, FACADE_ID, PROPERTY_TYPE_ID, SPACE',
'          INTO :P10_NEIGHBOURHOODS, :P10_STREET, :P10_BUILDING_USED, :P10_BUILDING_FACDE, :P10_BUILDING_TYPE, :P10_SPACE',
'          FROM REAL_STATE_DETAILS',
'         WHERE PRODUCT_ID = :P10_PRODUCT_ID;',
'',
'        SELECT SHORT_ADDRESS, BUILDING_NUMBER, STREET_NAME, NEIGHBOURHOOD_NAME, SUB_NUMBER, POSTAL_NUMBER',
'          INTO :P10_SHORT_TITLE, :P10_BUILDING_NUM, :P10_STREET_NA, :P10_NEIGH, :P10_SUBNUMBER, :P10_ZIP_CODE',
'          FROM INDIVIDUAL_REALESTATE_REQUESTS',
'         WHERE PRODUCT_ID = :P10_PRODUCT_ID;',
'',
'        SELECT COUNT(1) INTO v_count FROM PROPERTY_DIMENSIONS WHERE PRODUCT_ID = :P10_PRODUCT_ID;',
'',
'        IF v_count > 0 THEN',
'            FOR i IN (SELECT FACADE_ID, DESCRIPTION_AR FROM PROPERTY_DIMENSIONS WHERE PRODUCT_ID = :P10_PRODUCT_ID) LOOP',
'                IF NOT APEX_COLLECTION.COLLECTION_EXISTS (p_collection_name => ''AUCTION_BULIDING_LENGTH'') THEN',
'                    APEX_COLLECTION.CREATE_COLLECTION (p_collection_name => ''AUCTION_BULIDING_LENGTH'');',
'                END IF;',
'',
'                APEX_COLLECTION.ADD_MEMBER (',
'                    p_collection_name => ''AUCTION_BULIDING_LENGTH'',',
'                    p_c001 => i.FACADE_ID,',
'                    p_c002 => i.DESCRIPTION_AR',
'                );',
'            END LOOP;',
'        END IF;',
'',
'        SELECT COUNT(1) INTO v_count FROM PROPERTY_SERVICES WHERE PRODUCT_ID = :P10_PRODUCT_ID;',
'',
'        IF v_count > 0 THEN',
'            FOR j IN (SELECT SERVICE_ID, DESCRIPTION_AR FROM PROPERTY_SERVICES WHERE PRODUCT_ID = :P10_PRODUCT_ID) LOOP',
'                IF NOT APEX_COLLECTION.COLLECTION_EXISTS (p_collection_name => ''AUCTION_BULIDING_SERVICE'') THEN',
'                    APEX_COLLECTION.CREATE_COLLECTION (p_collection_name => ''AUCTION_BULIDING_SERVICE'');',
'                END IF;',
'',
'                APEX_COLLECTION.ADD_MEMBER (',
'                    p_collection_name => ''AUCTION_BULIDING_SERVICE'',',
'                    p_c001 => j.SERVICE_ID,',
'                    p_c002 => j.DESCRIPTION_AR',
'                );',
'            END LOOP;',
'        END IF;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>48660709434172021
);
end;
