,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    UPDATE REAL_STATE_DETAILS',
'       SET INSTRUMENT_NO = :P11_INSTRUMENT_NUM',
'     WHERE PRODUCT_ID = :P11_PRODUCT_ID;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20001, ''REAL_STATE_DETAILS Updating Error'');',
'    END IF;',
'',
'    UPDATE INDIVIDUAL_REALESTATE_REQUESTS',
'       SET INSTRUMENT_NUMBER        = :P11_INSTRUMENT_NUM,',
'           IS_INSTRUMENT_VALID      = :P11_INSTRUMENT_UP,',
'           INSTRUMENT_URL           = :P11_INSTRUMENT_URL,',
'           MORTGAGE_NOTES           = :P11_ALRAHN,',
'           OBLIGATIONS_NOTES        = :P11_LIABILITIES,',
'           AFFECTED_INFO_NOTES      = :P11_EFFECT,',
'           IS_PROPERTY_RATED        = :P11_EVALUATION,',
'           PROPERTY_RATED_URL       = :P11_PROPERTY_RATED_URL,',
'           HOW_RATE_PROPERTY        = :P11_ANT_EVALUATION,',
'           IS_SEND_RATE_TO_US       = :P11_CHECK,',
'           IS_FULLY_OWNED           = :P11_OWNED,',
'           OWNED_PERCENTAGE         = :P11_RATE,',
'           IS_FULLY_SELL            = :P11_FULLY_SOLID,',
'           SELL_AUTHORIZATION_URL   = :P11_AUTHORIZATION_URL,',
'           MINIMUM_SELL_PRICE       = :P11_MINIMUM_ACCEPTABLE_TO_SELL,',
'           BIRTHDAY                 = :P11_BIRTHDAY',
'     WHERE PRODUCT_ID = :P11_PRODUCT_ID;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20001, ''INDIVIDUAL_REALESTATE_REQUESTS Updating Error'');',
'    END IF;',
'END;'))
