'    IF :P11_PRODUCT_ID IS NOT NULL THEN',
'        SELECT INSTRUMENT_NUMBER, IS_INSTRUMENT_VALID, INSTRUMENT_URL, MORTGAGE_NOTES, OBLIGATIONS_NOTES, AFFECTED_INFO_NOTES, IS_PROPERTY_RATED, PROPERTY_RATED_URL,',
'               HOW_RATE_PROPERTY, IS_SEND_RATE_TO_US, IS_FULLY_OWNED, OWNED_PERCENTAGE, IS_FULLY_SELL, SELL_AUTHORIZATION_URL',
'          INTO :P11_INSTRUMENT_NUM, :P11_INSTRUMENT_UP, :P11_INSTRUMENT_URL, :P11_ALRAHN, :P11_LIABILITIES, :P11_EFFECT, :P11_EVALUATION, :P11_PROPERTY_RATED_URL,',
'               :P11_ANT_EVALUATION, :P11_CHECK, :P11_OWNED, :P11_RATE, :P11_FULLY_SOLID, :P11_AUTHORIZATION_URL',
'          FROM INDIVIDUAL_REALESTATE_REQUESTS',
'         WHERE PRODUCT_ID = :P11_PRODUCT_ID;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>48661359908172027
);
