wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(136189438233352132)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update Terms Confirmation'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_name      VARCHAR2(1000);',
'    l_buyer_name VARCHAR2(1000);',
'    l_result    NUMBER;',
'    l_message   VARCHAR2(1000);',
'BEGIN',
'    SELECT LOOKUPS_MNT.lookup_detail_name_by_id (p_lookup_detail_id => PROPERTY_TYPE_ID, p_lang => ''ar'')',
'           || '' '' || LOOKUPS_MNT.lookup_detail_name_by_id (p_lookup_detail_id => USAGE_ID, p_lang => ''ar'')',
unistr('           || '' '' || ''\0631\0642\0645 \0627\0644\0635\0643 '' || INSTRUMENT_NO'),
'      INTO v_name',
'      FROM REAL_STATE_DETAILS',
'     WHERE PRODUCT_ID = :P12_PRODUCT_ID;',
'',
'    UPDATE PRODUCTS',
'       SET NAME_AR = v_name',
'     WHERE ID = :P12_PRODUCT_ID;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20001, ''PRODUCTS Updating Error'');',
'    END IF;',
'',
'    UPDATE INDIVIDUAL_REALESTATE_REQUESTS',
'       SET IS_ACCEPT_TERMS_AND_CONDITIONS = :P12_APPROVE',
'     WHERE PRODUCT_ID = :P12_PRODUCT_ID;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20002, ''INDIVIDUAL_REALESTATE_REQUESTS Updating Error'');',
'    END IF;',
'',
unistr('    APEX_APPLICATION.g_print_success_message := ''<span class="apex-success-msg"> \062A\0645 \062A\0646\0641\064A\0630 \0637\0644\0628\0643 \0628\0646\062C\0627\062D </span>'';'),
'   ',
'    -- SEND EMAIL TO THE ADMIN',
'    --   SELECT BUYER_NAME',
'    --     INTO l_buyer_name',
'    --     FROM INDIVIDUAL_REALESTATE_REQUESTS',
