'       (select ZA_SAKU_ALEAQAR.INSTRUMENT_UP  from ZA_SAKU_ALEAQAR where ZA_SAKU_ALEAQAR.ORDER_REQUEST=ZA_AUCTION_BUILDINGS.ID )as  INSTRUMENT,',
'       CASE',
unistr('    WHEN ZA_SAKU_ALEAQAR.INSTRUMENT_UP = 1 THEN ''\0646\0639\0645'''),
unistr('    WHEN ZA_SAKU_ALEAQAR.INSTRUMENT_UP = 2 THEN ''\0644\0627'''),
'        END AS   INSTRUMENT_UP,',
'       (select ZA_SAKU_ALEAQAR.APPROV from ZA_SAKU_ALEAQAR where ZA_SAKU_ALEAQAR.ORDER_REQUEST=ZA_AUCTION_BUILDINGS.ID )as  APPROV1,',
'          CASE',
unistr('    WHEN ZA_SAKU_ALEAQAR.APPROV = 0 THEN ''  \0627\0644\0637\0644\0628 \063A\064A\0631 \0645\0643\062A\0627\0645\0644 \064A\062C\0628 \062A\062D\062F\062B \0627\0644\0635\0643 '''),
unistr('    WHEN ZA_SAKU_ALEAQAR.APPROV = 1 THEN '' \0627\0644\0637\0644\0628 \0642\064A\062F \0627\0644\0645\0631\0627\062C\0639\0629 \0645\0646 \0627\0644\0627\062F\0627\0631\0629 '''),
'END AS APPROV ',
