 p_id=>wwv_flow_imp.id(164352162813919516)
,p_name=>unistr('\0645\0639\0644\0648\0645\0627\062A \0627\0644\0635\0643')
,p_template=>wwv_flow_imp.id(157080680789697673)
,p_display_sequence=>90
,p_region_template_options=>'#DEFAULT#:t-Region--accent15:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ID,',
'       ORDER_REQUEST,',
'       TYPE_SELLER_ORDER,',
'     case ',
unistr('     when INSTRUMENT_UP =1 then ''\0646\0639\0645'''),
unistr('     when INSTRUMENT_UP =2 then ''\0644\0627\0621'''),
'     END INSTRUMENT_UP,',
'       dbms_lob.getlength(FILE_INS_BLOB) view_file,',
'       dbms_lob.getlength(FILE_INS_BLOB) dwonload,',
'       case ',
unistr('     when ALRAHN =1 then ''\0646\0639\0645'''),
unistr('     when ALRAHN =2 then ''\0644\0627\0621'''),
'     END ALRAHN,',
'       dbms_lob.getlength(ALRHN_BLOB) view_file1,',
'       dbms_lob.getlength(ALRHN_BLOB) dwonload1,',
'       case ',
unistr('     when LIABILITIES =1 then ''\0646\0639\0645'''),
unistr('     when LIABILITIES =2 then ''\0644\0627\0621'''),
'     END LIABILITIES,',
'       dbms_lob.getlength(LIAB_BLOB) view_file2,',
'       dbms_lob.getlength(LIAB_BLOB) dwonload2,',
'        case ',
unistr('     when EFFECT =1 then ''\0646\0639\0645'''),
unistr('     when EFFECT =2 then ''\0644\0627\0621'''),
'     END EFFECT,',
'       dbms_lob.getlength(EFFECT_BLOB) view_file3,',
'       dbms_lob.getlength(EFFECT_BLOB) dwonload3,',
'       case ',
unistr('     when EVALUATIONS =1 then ''\0646\0639\0645'''),
unistr('     when EVALUATIONS =2 then ''\0644\0627\0621'''),
'     END EVALUATIONS,',
'      dbms_lob.getlength(EVALUTION_BLOB) view_file4,',
'       dbms_lob.getlength(EVALUTION_BLOB) dwonload4,',
'       ANT_EVALUATION,',
'       case ',
unistr('     when OWNED =1 then ''\0646\0639\0645'''),
unistr('     when OWNED =2 then ''\0644\0627\0621'''),
'     END OWNED,',
'       RATE,',
'       case ',
unistr('     when FULLY_SOLID =1 then ''\0646\0639\0645'''),
unistr('     when FULLY_SOLID =2 then ''\0644\0627\0621'''),
'     END FULLY_SOLID,',
'        dbms_lob.getlength(FULL_BLOB) view_file5,',
'       dbms_lob.getlength(FULL_BLOB) dwonload5,',
'       SOLD_RATIO,',
'       INSTRUMENT_NUM',
'  from ZA_SAKU_ALEAQAR where ORDER_REQUEST =to_number(:P16_ROW_ID) and rownum=1  order by ORDER_REQUEST desc'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P16_ROW_ID'
